-- Candidate only. A marker attempt must first be quarantined in REVIEW.
-- Neither a cooldown nor a human attestation proves that a previously sent
-- Sheets request has stopped. Real request drain and editor exclusion remain
-- mandatory. No provider mutation, job reset, lock release, or row position.
CREATE TABLE personal_marker_review_recovery_actions (
  recovery_action_id TEXT NOT NULL PRIMARY KEY,
  marker_action_id TEXT NOT NULL,
  spreadsheet_id TEXT NOT NULL,
  sheet_name TEXT NOT NULL,
  personal_use_id TEXT NOT NULL,
  metadata_id INTEGER NOT NULL CHECK(metadata_id BETWEEN 1 AND 2147483647),
  remediation_token TEXT NOT NULL,
  source_version INTEGER NOT NULL CHECK(source_version>0),
  source_revision INTEGER NOT NULL CHECK(source_revision>0),
  source_fingerprint TEXT NOT NULL CHECK(length(source_fingerprint)=64 AND source_fingerprint NOT GLOB '*[^0-9a-f]*'),
  cutover_generation TEXT NOT NULL,
  decision TEXT NOT NULL CHECK(decision IN ('MATCH_INTENDED','PROVEN_NO_OP')),
  evidence_digest TEXT NOT NULL CHECK(length(evidence_digest)=64 AND evidence_digest NOT GLOB '*[^0-9a-f]*'),
  principal TEXT NOT NULL CHECK(principal='ADMIN_TOKEN'),
  reason TEXT NOT NULL CHECK(length(reason) BETWEEN 5 AND 200),
  state TEXT NOT NULL CHECK(state IN ('APPROVED','APPLIED','CANCELLED')),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL CHECK(expires_at>created_at)
);
CREATE UNIQUE INDEX personal_marker_review_one_approval ON personal_marker_review_recovery_actions(marker_action_id) WHERE state='APPROVED';
CREATE TABLE personal_marker_review_atomic_assertions(assertion_id TEXT NOT NULL PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1));

CREATE TRIGGER personal_marker_review_approval_admit BEFORE INSERT ON personal_marker_review_recovery_actions
WHEN NEW.state<>'APPROVED' OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR abs((julianday(NEW.created_at)-julianday('now'))*86400)>60 OR length(NEW.expires_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.expires_at) IS NOT NEW.expires_at OR NOT EXISTS(
 SELECT 1 FROM personal_historical_marker_actions a JOIN personal_historical_enrollment_intents i ON i.spreadsheet_id=a.spreadsheet_id AND i.sheet_name=a.sheet_name AND i.personal_use_id=a.personal_use_id AND i.metadata_id=a.metadata_id AND i.source_version=a.source_version AND i.source_revision=a.source_revision AND i.source_fingerprint=a.source_fingerprint AND i.cutover_generation=a.cutover_generation AND i.operation_token=a.operation_token AND i.outer_token=a.outer_token AND i.state='REVIEW'
 JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW'
 JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id
 JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' AND substr(p.transaction_date,1,7)=i.month
 JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED'
 JOIN personal_projection_admissions d ON d.personal_use_id=i.personal_use_id AND d.sequence=i.admission_sequence
 JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE'
 JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD'
 WHERE a.action_id=NEW.marker_action_id AND a.kind='ATTACH_ABSENT' AND a.spreadsheet_id=NEW.spreadsheet_id AND a.sheet_name=NEW.sheet_name AND a.personal_use_id=NEW.personal_use_id AND a.metadata_id=NEW.metadata_id AND a.remediation_token=NEW.remediation_token AND a.source_version=NEW.source_version AND a.source_revision=NEW.source_revision AND a.source_fingerprint=NEW.source_fingerprint AND a.cutover_generation=NEW.cutover_generation AND a.state='REVIEW' AND i.admission_sequence<=i.admission_watermark
 AND julianday(a.updated_at)<=julianday('now','-15 minutes') AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes')
 AND NOT EXISTS(SELECT 1 FROM sync_jobs s WHERE s.entity_type='PERSONAL_USE' AND (s.status='PROCESSING' OR (s.entity_key=i.personal_use_id AND s.status='REVIEW')))
 AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents j WHERE j.spreadsheet_id=i.spreadsheet_id AND j.sheet_name=i.sheet_name AND (j.personal_use_id=i.personal_use_id OR j.state='IN_FLIGHT'))
 AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW'))
 AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision))))
 AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision))))
) OR NOT EXISTS(SELECT 1 FROM personal_marker_review_atomic_assertions x WHERE x.assertion_id=NEW.recovery_action_id AND x.ok=1) OR NOT EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.action='HISTORICAL_MARKER_REVIEW_APPROVED' AND audit.entity_key=NEW.personal_use_id AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.recoveryActionId')=NEW.recovery_action_id AND json_extract(audit.after_json,'$.actionId')=NEW.marker_action_id ELSE 0 END )
BEGIN SELECT RAISE(ABORT,'MARKER_REVIEW_APPROVAL_REQUIRED'); END;
CREATE TRIGGER personal_marker_review_action_no_delete BEFORE DELETE ON personal_marker_review_recovery_actions BEGIN SELECT RAISE(ABORT,'MARKER_REVIEW_AUDIT_REQUIRED'); END;
CREATE TRIGGER personal_marker_review_action_no_replace BEFORE INSERT ON personal_marker_review_recovery_actions WHEN EXISTS(SELECT 1 FROM personal_marker_review_recovery_actions a WHERE a.rowid=NEW.rowid OR a.recovery_action_id=NEW.recovery_action_id) BEGIN SELECT RAISE(ABORT,'MARKER_REVIEW_AUDIT_REQUIRED'); END;
CREATE TRIGGER personal_marker_review_action_no_rowid_replace BEFORE UPDATE ON personal_marker_review_recovery_actions WHEN EXISTS(SELECT 1 FROM personal_marker_review_recovery_actions a WHERE a.rowid=NEW.rowid AND a.rowid<>OLD.rowid) BEGIN SELECT RAISE(ABORT,'MARKER_REVIEW_AUDIT_REQUIRED'); END;
CREATE TRIGGER personal_marker_review_action_immutable BEFORE UPDATE OF recovery_action_id,marker_action_id,spreadsheet_id,sheet_name,personal_use_id,metadata_id,remediation_token,source_version,source_revision,source_fingerprint,cutover_generation,decision,evidence_digest,principal,reason,created_at,expires_at ON personal_marker_review_recovery_actions BEGIN SELECT RAISE(ABORT,'MARKER_REVIEW_AUDIT_REQUIRED'); END;
CREATE TRIGGER personal_marker_review_action_transition BEFORE UPDATE OF state ON personal_marker_review_recovery_actions
WHEN OLD.state IS NOT NEW.state AND NOT (OLD.state='APPROVED' AND (NEW.state='CANCELLED' OR (NEW.state='APPLIED' AND OLD.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM personal_historical_marker_actions a JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=a.spreadsheet_id AND l.sheet_name=a.sheet_name AND l.personal_use_id=a.personal_use_id AND l.metadata_id=a.metadata_id AND l.state='REVIEW' WHERE a.action_id=OLD.marker_action_id AND a.remediation_token=OLD.remediation_token AND ((OLD.decision='MATCH_INTENDED' AND a.state='VERIFIED' AND a.post_digest=OLD.evidence_digest) OR (OLD.decision='PROVEN_NO_OP' AND a.state='CANCELLED' AND a.post_digest IS NULL)))))
 AND EXISTS(SELECT 1 FROM personal_marker_review_atomic_assertions x WHERE x.assertion_id=OLD.recovery_action_id AND x.ok=1) AND EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.entity_key=OLD.personal_use_id AND audit.action=CASE WHEN NEW.state='CANCELLED' THEN 'HISTORICAL_MARKER_REVIEW_CANCELLED' WHEN OLD.decision='MATCH_INTENDED' THEN 'HISTORICAL_MARKER_VERIFIED' ELSE 'HISTORICAL_MARKER_CANCELLED' END AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.recoveryActionId')=OLD.recovery_action_id AND json_extract(audit.after_json,'$.actionId')=OLD.marker_action_id ELSE 0 END )
) BEGIN SELECT RAISE(ABORT,'MARKER_REVIEW_TRANSITION_INVALID'); END;

-- Preserve 0055 transitions and add only exact audited REVIEW outcomes.
DROP TRIGGER historical_marker_action_transition;
CREATE TRIGGER historical_marker_action_transition BEFORE UPDATE OF state,updated_at ON personal_historical_marker_actions
WHEN OLD.state IS NOT NEW.state AND NOT (
 (OLD.state='APPROVED' AND NEW.state='DISPATCHED' AND OLD.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW' JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED' JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE' JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD' WHERE i.spreadsheet_id=OLD.spreadsheet_id AND i.sheet_name=OLD.sheet_name AND i.personal_use_id=OLD.personal_use_id AND i.metadata_id=OLD.metadata_id AND i.source_version=OLD.source_version AND i.source_revision=OLD.source_revision AND i.source_fingerprint=OLD.source_fingerprint AND i.cutover_generation=OLD.cutover_generation AND i.operation_token=OLD.operation_token AND i.outer_token=OLD.outer_token AND i.state='REVIEW' AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM sync_jobs s WHERE s.entity_type='PERSONAL_USE' AND (s.status='PROCESSING' OR (s.entity_key=i.personal_use_id AND s.status='REVIEW'))) AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents p2 WHERE p2.spreadsheet_id=i.spreadsheet_id AND p2.sheet_name=i.sheet_name AND (p2.personal_use_id=i.personal_use_id OR p2.state='IN_FLIGHT')) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW')))) OR
 (OLD.state='DISPATCHED' AND NEW.state='VERIFIED' AND NEW.post_digest IS NOT NULL AND EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW' JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED' JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE' JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD' WHERE i.spreadsheet_id=OLD.spreadsheet_id AND i.sheet_name=OLD.sheet_name AND i.personal_use_id=OLD.personal_use_id AND i.metadata_id=OLD.metadata_id AND i.source_version=OLD.source_version AND i.source_revision=OLD.source_revision AND i.source_fingerprint=OLD.source_fingerprint AND i.cutover_generation=OLD.cutover_generation AND i.operation_token=OLD.operation_token AND i.outer_token=OLD.outer_token AND i.state='REVIEW' AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM sync_jobs busy WHERE busy.entity_type='PERSONAL_USE' AND (busy.status='PROCESSING' OR (busy.entity_key=i.personal_use_id AND busy.status='REVIEW'))) AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents p2 WHERE p2.spreadsheet_id=i.spreadsheet_id AND p2.sheet_name=i.sheet_name AND (p2.personal_use_id=i.personal_use_id OR p2.state='IN_FLIGHT')) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW')))) OR
 (OLD.state='DISPATCHED' AND NEW.state='REVIEW') OR
 (OLD.state='APPROVED' AND NEW.state='CANCELLED') OR
 (OLD.state='REVIEW' AND NEW.state='VERIFIED' AND NEW.post_digest IS NOT NULL AND EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW' JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED' JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE' JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD' WHERE i.spreadsheet_id=OLD.spreadsheet_id AND i.sheet_name=OLD.sheet_name AND i.personal_use_id=OLD.personal_use_id AND i.metadata_id=OLD.metadata_id AND i.source_version=OLD.source_version AND i.source_revision=OLD.source_revision AND i.source_fingerprint=OLD.source_fingerprint AND i.cutover_generation=OLD.cutover_generation AND i.operation_token=OLD.operation_token AND i.outer_token=OLD.outer_token AND i.state='REVIEW' AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM sync_jobs busy WHERE busy.entity_type='PERSONAL_USE' AND (busy.status='PROCESSING' OR (busy.entity_key=i.personal_use_id AND busy.status='REVIEW'))) AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents p2 WHERE p2.spreadsheet_id=i.spreadsheet_id AND p2.sheet_name=i.sheet_name AND (p2.personal_use_id=i.personal_use_id OR p2.state='IN_FLIGHT')) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW'))) AND EXISTS(SELECT 1 FROM personal_marker_review_recovery_actions rr JOIN personal_marker_review_atomic_assertions ar ON ar.assertion_id=rr.recovery_action_id AND ar.ok=1 JOIN personal_historical_marker_atomic_assertions am ON am.assertion_id=rr.marker_action_id AND am.ok=1 JOIN admin_audit audit ON audit.entity_key=rr.personal_use_id AND audit.action='HISTORICAL_MARKER_VERIFIED' WHERE rr.marker_action_id=OLD.action_id AND OLD.kind='ATTACH_ABSENT' AND rr.spreadsheet_id=OLD.spreadsheet_id AND rr.sheet_name=OLD.sheet_name AND rr.personal_use_id=OLD.personal_use_id AND rr.metadata_id=OLD.metadata_id AND rr.remediation_token=OLD.remediation_token AND rr.source_version=OLD.source_version AND rr.source_revision=OLD.source_revision AND rr.source_fingerprint=OLD.source_fingerprint AND rr.cutover_generation=OLD.cutover_generation AND rr.decision='MATCH_INTENDED' AND rr.state='APPROVED' AND rr.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND julianday(OLD.updated_at)<=julianday('now','-15 minutes') AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.actionId')=OLD.action_id AND json_extract(audit.after_json,'$.recoveryActionId')=rr.recovery_action_id ELSE 0 END ) AND EXISTS(SELECT 1 FROM personal_marker_review_recovery_actions rr2 WHERE rr2.marker_action_id=OLD.action_id AND rr2.state='APPROVED' AND rr2.decision='MATCH_INTENDED' AND rr2.evidence_digest=NEW.post_digest)) OR
 (OLD.state='REVIEW' AND NEW.state='CANCELLED' AND NEW.post_digest IS NULL AND EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW' JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED' JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE' JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD' WHERE i.spreadsheet_id=OLD.spreadsheet_id AND i.sheet_name=OLD.sheet_name AND i.personal_use_id=OLD.personal_use_id AND i.metadata_id=OLD.metadata_id AND i.source_version=OLD.source_version AND i.source_revision=OLD.source_revision AND i.source_fingerprint=OLD.source_fingerprint AND i.cutover_generation=OLD.cutover_generation AND i.operation_token=OLD.operation_token AND i.outer_token=OLD.outer_token AND i.state='REVIEW' AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM sync_jobs busy WHERE busy.entity_type='PERSONAL_USE' AND (busy.status='PROCESSING' OR (busy.entity_key=i.personal_use_id AND busy.status='REVIEW'))) AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents p2 WHERE p2.spreadsheet_id=i.spreadsheet_id AND p2.sheet_name=i.sheet_name AND (p2.personal_use_id=i.personal_use_id OR p2.state='IN_FLIGHT')) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW'))) AND EXISTS(SELECT 1 FROM personal_marker_review_recovery_actions rr JOIN personal_marker_review_atomic_assertions ar ON ar.assertion_id=rr.recovery_action_id AND ar.ok=1 JOIN personal_historical_marker_atomic_assertions am ON am.assertion_id=rr.marker_action_id AND am.ok=1 JOIN admin_audit audit ON audit.entity_key=rr.personal_use_id AND audit.action='HISTORICAL_MARKER_CANCELLED' WHERE rr.marker_action_id=OLD.action_id AND OLD.kind='ATTACH_ABSENT' AND rr.spreadsheet_id=OLD.spreadsheet_id AND rr.sheet_name=OLD.sheet_name AND rr.personal_use_id=OLD.personal_use_id AND rr.metadata_id=OLD.metadata_id AND rr.remediation_token=OLD.remediation_token AND rr.source_version=OLD.source_version AND rr.source_revision=OLD.source_revision AND rr.source_fingerprint=OLD.source_fingerprint AND rr.cutover_generation=OLD.cutover_generation AND rr.decision='PROVEN_NO_OP' AND rr.state='APPROVED' AND rr.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND julianday(OLD.updated_at)<=julianday('now','-15 minutes') AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.actionId')=OLD.action_id AND json_extract(audit.after_json,'$.recoveryActionId')=rr.recovery_action_id ELSE 0 END ))
) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_TRANSITION_INVALID'); END;

DROP TRIGGER historical_marker_action_post_digest;
CREATE TRIGGER historical_marker_action_post_digest BEFORE UPDATE OF post_digest ON personal_historical_marker_actions WHEN OLD.post_digest IS NOT NEW.post_digest AND NOT (OLD.state='DISPATCHED' AND NEW.state='VERIFIED' AND OLD.post_digest IS NULL AND NEW.post_digest IS NOT NULL) AND NOT (OLD.state='REVIEW' AND NEW.state='VERIFIED' AND OLD.post_digest IS NULL AND NEW.post_digest IS NOT NULL AND EXISTS(SELECT 1 FROM personal_marker_review_recovery_actions rr JOIN personal_marker_review_atomic_assertions ar ON ar.assertion_id=rr.recovery_action_id AND ar.ok=1 JOIN personal_historical_marker_atomic_assertions am ON am.assertion_id=rr.marker_action_id AND am.ok=1 JOIN admin_audit audit ON audit.entity_key=rr.personal_use_id AND audit.action='HISTORICAL_MARKER_VERIFIED' WHERE rr.marker_action_id=OLD.action_id AND OLD.kind='ATTACH_ABSENT' AND rr.spreadsheet_id=OLD.spreadsheet_id AND rr.sheet_name=OLD.sheet_name AND rr.personal_use_id=OLD.personal_use_id AND rr.metadata_id=OLD.metadata_id AND rr.remediation_token=OLD.remediation_token AND rr.source_version=OLD.source_version AND rr.source_revision=OLD.source_revision AND rr.source_fingerprint=OLD.source_fingerprint AND rr.cutover_generation=OLD.cutover_generation AND rr.decision='MATCH_INTENDED' AND rr.state='APPROVED' AND rr.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND julianday(OLD.updated_at)<=julianday('now','-15 minutes') AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.actionId')=OLD.action_id AND json_extract(audit.after_json,'$.recoveryActionId')=rr.recovery_action_id ELSE 0 END ) AND EXISTS(SELECT 1 FROM personal_marker_review_recovery_actions rr2 WHERE rr2.marker_action_id=OLD.action_id AND rr2.state='APPROVED' AND rr2.decision='MATCH_INTENDED' AND rr2.evidence_digest=NEW.post_digest)) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;
